namespace FileSystemOS.Systeme
{
    /// <summary>
    /// LE GUIDE DU FILE SYST LANGAGE, DEJA FABRIQUE (PDF de 41 548 octets, 11 pages).
    ///
    /// Produit hors de l'OS par le meme programme que Utils/PdfEcrivain.cs et avec le meme contenu
    /// que GuideFsl.Fabriquer (memes 94 blocs, meme annexe des fonctions), puis embarque. Le
    /// fabriquer DANS l'OS creait des dizaines de milliers de petites chaines (session bloquee sur
    /// "session : guide du FSL", 1.28).
    ///
    /// Il est range en TEXTE BASE64, en 14 morceaux de 4 000 caracteres, et non en tableau
    /// d'octets ecrit en dur : un tableau de 41 548 octets faisait planter IL2CPU a la
    /// compilation (MSB6006, code -1073741819 = violation d'acces, 1.28.1). Cosmos range ses
    /// polices de la meme facon. Le decodeur est le notre (valide en Python : octets identiques,
    /// tous les cas de bourrage) ; il ne sert qu'une fois, quand le guide est ecrit.
    /// </summary>
    public static class GuidePdf
    {
        private static byte[] octets;

        /// <summary>Le PDF, decode a la premiere demande.</summary>
        public static byte[] Octets
        {
            get
            {
                if (octets == null) octets = Decoder(Morceaux);
                return octets;
            }
        }

        private static int Valeur(char c)
        {
            if (c >= 'A' && c <= 'Z') return c - 'A';
            if (c >= 'a' && c <= 'z') return c - 'a' + 26;
            if (c >= '0' && c <= '9') return c - '0' + 52;
            if (c == '+') return 62;
            if (c == '/') return 63;
            return -1;                                   // '=' (bourrage) et tout le reste : ignores
        }

        private static byte[] Decoder(string[] morceaux)
        {
            int total = 0;
            for (int i = 0; i < morceaux.Length; i++) total += morceaux[i].Length;
            byte[] r = new byte[total / 4 * 3];
            int n = 0, acc = 0, bits = 0;
            for (int i = 0; i < morceaux.Length; i++)
            {
                string m = morceaux[i];
                for (int k = 0; k < m.Length; k++)
                {
                    int v = Valeur(m[k]);
                    if (v < 0) continue;
                    acc = (acc << 6) | v;
                    bits += 6;
                    if (bits >= 8)
                    {
                        bits -= 8;
                        r[n++] = (byte)(acc >> bits);
                        acc &= (1 << bits) - 1;
                    }
                }
            }
            if (n == r.Length) return r;
            byte[] juste = new byte[n];
            for (int i = 0; i < n; i++) juste[i] = r[i];
            return juste;
        }

        private static readonly string[] Morceaux =
        {
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            ""
        };
    }
}
